(()=>{'use strict';const svg=n=>`<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${n}"></use></svg>`;let toastTimer;function toast(text){document.querySelector('.helper-file-toast')?.remove();clearTimeout(toastTimer);const el=document.createElement('div');el.className='helper-file-toast';el.setAttribute('role','alert');const p=document.createElement('p');p.textContent=text;const close=document.createElement('button');close.type='button';close.setAttribute('aria-label','Dismiss file notification');close.innerHTML=svg('close');close.onclick=()=>el.remove();el.append(p,close);document.body.append(el);toastTimer=setTimeout(()=>el.remove(),6000);}
const valid=text=>!/\0/.test(text)&&/(GTA5 UUID|\[RAGE\]|\[macport\]|GTA V.*crash|Game hung for|Unable to find critical archive|compat built|ReflectionMSAA|sample count.*supported|memory:\s*footprint)/i.test(text);
function review(text){const lines=['Basic log review (processed on this device).'];const hang=text.match(/Game hung for\s+([\d.]+)\s*s/i),memory=text.match(/memory:\s*footprint\s+(\d+)\s*MB.*?(\d+)\s*MB left/i),thermal=text.match(/thermal\s*[:=]?\s*(nominal|fair|serious|critical)/i);if(hang)lines.push(`The log records a ${hang[1]}-second hang. This means the game stopped responding; the log excerpt alone does not establish the cause.`);if(memory)lines.push(`Recorded memory footprint: ${memory[1]} MB. Recorded remaining app memory: ${memory[2]} MB. This is from the logged session, not a live device scan.`);if(thermal)lines.push(`Recorded thermal state: ${thermal[1].toLowerCase()}.`);const missing=text.match(/Unable to find critical archive[^\n]*/i);if(missing)lines.push('A game archive could not be found. Check that the complete game data is copied to the expected folder before retrying.');if(memory&&+memory[2]<150)lines.push('The recorded memory headroom is low. Try the lowest launcher preset and a lower resolution, then reproduce the issue once. This is a precaution, not confirmation of a memory crash.');if(thermal&&/serious|critical/i.test(thermal[1]))lines.push('Let the device cool before testing again.');if(!hang&&!memory&&!thermal&&!missing)lines.push('The file contains GTA V diagnostic markers, but this basic review cannot determine the failure.');lines.push('Include your device, OS version, build, and what happened just before the issue when asking the community.');return lines.join('\n\n');}
window.FranklinLogReview={valid,review};
function attach(){const form=document.querySelector('.ask-franklin-form');if(!form||form.querySelector('.helper-attach'))return false;const send=form.querySelector('.ask-franklin-send'),question=form.querySelector('.ask-franklin-input');let file=null,excerpt='',busy=false,revision=0;const input=document.createElement('input');input.type='file';input.accept='.log,.txt,text/plain';input.hidden=true;input.setAttribute('aria-label','Choose GTA V log');const pick=document.createElement('button');pick.type='button';pick.className='helper-attach';pick.setAttribute('aria-label','Attach GTA V log');pick.title='Attach GTA V log (.log or .txt)';pick.innerHTML=svg('paperclip');form.insertBefore(pick,send);form.append(input);const paste=document.createElement('button');paste.type='button';paste.className='helper-paste';paste.setAttribute('aria-label','Paste into message');paste.title='Paste';paste.innerHTML='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="4" width="8" height="4" rx="1"/><path d="M8 6H5v15h14V6h-3M8 12h8M8 16h6"/></svg>';form.insertBefore(paste,pick);paste.onclick=async()=>{try{const value=await navigator.clipboard.readText();if(!value){toast('Your clipboard is empty.');return;}const start=question.selectionStart??question.value.length,end=question.selectionEnd??start;const next=question.value.slice(0,start)+value+question.value.slice(end);if(next.length>question.maxLength){toast('This text is too long. Attach a .log or .txt file instead.');return;}question.value=next;question.focus({preventScroll:true});question.setSelectionRange(start+value.length,start+value.length);question.dispatchEvent(new Event('input',{bubbles:true}));}catch{question.focus({preventScroll:true});toast('Clipboard access was blocked. Touch and hold the message field, then choose Paste.');}};form.classList.add('has-log-attachment');const bar=document.createElement('div');bar.className='helper-attached-file';bar.hidden=true;const name=document.createElement('span'),share=document.createElement('button'),remove=document.createElement('button');share.type=remove.type='button';share.innerHTML=svg('arrow-up-right');share.setAttribute('aria-label','Share original log file');remove.innerHTML=svg('close');remove.setAttribute('aria-label','Remove attached log');bar.append(name,share,remove);form.before(bar);const note=document.createElement('p');note.className='helper-attachment-note';note.hidden=true;note.textContent='Send reviews an excerpt. File sharing uses the original. Check personal details before sending.';bar.after(note);
const clear=()=>{revision++;file=null;excerpt='';input.value='';bar.hidden=note.hidden=true;send.disabled=busy||!question.value.trim();pick.setAttribute('aria-label','Attach GTA V log');};document.addEventListener('franklin-disconnect',()=>{busy=false;clear();pick.disabled=false;document.querySelector('.helper-file-toast')?.remove();});pick.onclick=()=>input.click();remove.onclick=clear;
input.onchange=async()=>{const selected=input.files?.[0];clear();if(!selected)return;if(!/\.(log|txt)$/i.test(selected.name)||selected.size>524288||selected.size===0){toast('Choose a GTA V .log or .txt file, up to 512 KB.');return;}const version=revision;try{const text=await selected.text();if(version!==revision)return;if(!valid(text)){toast('This file does not look like a GTA V log. Choose run.log, run.prev.log, or crash-*.txt from GTA V > Logs.');return;}file=selected;const lines=text.split(/\r?\n/),indexes=new Set();lines.forEach((l,i)=>{if(i<25||i>=lines.length-70||/fatal|error|crash|exception|signal|memory|sample count|critical archive|compat built|GTA5 UUID|stalled|Game hung/i.test(l))for(let j=Math.max(0,i-1);j<=Math.min(lines.length-1,i+1);j++)indexes.add(j);});excerpt=[...indexes].sort((a,b)=>a-b).map(i=>lines[i]).join('\n').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig,'[email removed]').replace(/(authorization\s*[:=]\s*|token\s*[:=]\s*|api[_-]?key\s*[:=]\s*)\S+/ig,'$1[removed]').slice(0,90000);name.textContent=selected.name+' · '+Math.ceil(selected.size/1024)+' KB';name.title=selected.name;bar.hidden=note.hidden=false;send.disabled=busy;share.hidden=!(navigator.canShare&&navigator.canShare({files:[selected]}));pick.setAttribute('aria-label','Replace attached GTA V log');}catch{toast('Unable to read this file. Please choose a text log.');}};
// Existing input listeners disable Send for empty text. An attached log is also sendable.
question.addEventListener('input',()=>{queueMicrotask(()=>{if(file&&!busy)send.disabled=false;});});
share.onclick=async()=>{if(!file)return;try{await navigator.share({files:[file],title:'GTA V support log'});}catch(e){if(e.name!=='AbortError')toast('Unable to share. Attach the log manually in Discord.');}};
function message(text,role){const list=document.querySelector('.ask-franklin-messages');if(!list)return;const row=document.createElement('div');row.className='ask-franklin-message '+role+' helper-log-result';if(role==='bot'){const avatar=document.createElement('span');avatar.className='mini-avatar';avatar.textContent='F';row.append(avatar);}const bubble=document.createElement('div');bubble.className='bubble';bubble.style.whiteSpace='pre-wrap';bubble.textContent=text;row.append(bubble);list.append(row);list.scrollTop=list.scrollHeight;return bubble;}
async function submit(e){const generation=window.FranklinSession?.generation;if(!file){if(/(?:check|review|analy[sz]e|cek|periksa).*\blog\b/i.test(question.value)){e.preventDefault();e.stopImmediatePropagation();toast('Attach run.log, run.prev.log, or crash-*.txt using the paperclip beside Send.');message('Please attach your GTA V log using the paperclip beside Send. Once selected, press Send to review it.','bot');}return;}e.preventDefault();e.stopImmediatePropagation();if(busy)return;busy=true;send.disabled=pick.disabled=true;const text=excerpt,filename=file.name,q=question.value.trim();message((q?q+'\n':'')+'Attached log: '+filename,'user');question.value='';const bubble=message('Reviewing your log…','bot');clear();try{await window.FranklinSupportContext?.ingestLog(text);const answer=await window.FranklinDeveloperKB?.answer((q||'GTA V crash log')+'\n'+text);if(generation!==window.FranklinSession?.generation)return;await window.FranklinTyping.reveal(bubble,answer?.topic==='developer-troubleshooting'?answer.text:review(text)+(answer?.topic==='developer-triage'?'\n\nNext steps:\n'+answer.text:''));}catch{if(generation!==window.FranklinSession?.generation)return;await window.FranklinTyping.reveal(bubble,review(text));}finally{if(generation!==window.FranklinSession?.generation)return;busy=false;pick.disabled=false;send.disabled=!file&&!question.value.trim();const list=document.querySelector('.ask-franklin-messages');if(list)list.scrollTop=list.scrollHeight;}}
document.addEventListener('submit',e=>{if(e.target===form)submit(e);},true);return true;}
const l=document.createElement('link');l.rel='stylesheet';l.href='franklin-log-files.css?v=20261027profile';document.head.append(l);if(!attach()){const observer=new MutationObserver(()=>{if(attach())observer.disconnect();});observer.observe(document.body,{childList:true,subtree:true});setTimeout(()=>observer.disconnect(),30000);}})();
